import { readFileSync } from "node:fs";
import { renderToString } from "react-dom/server";
import { describe, expect, it } from "vitest";
import Peek from "./Peek.js";

describe("Peek SSR", () => {
  it("renders the dialog and its content", () => {
    const html = renderToString(
      <Peek anchor="--entity-chip-a" label="Preview of Button">
        Card
      </Peek>,
    );
    expect(html).toContain("ds peek");
    expect(html).toContain('role="dialog"');
    expect(html).toContain("Card");
  });

  it("hides a peek that holds only its label in its stylesheet", () => {
    const styles = readFileSync(
      new URL("./styles.css", import.meta.url),
      "utf8",
    );
    expect(styles).toMatch(
      /\.ds\.peek:not\(:has\(> :not\(\[hidden\]\)\)\) \{\s*display: none;\s*\}/,
    );
  });
});
